<template><dialog ref="dialog" class="bio-nexus-dialog exam-dialog" @cancel.prevent="close"><form class="dialog-shell" @submit.prevent="submit"><header class="dialog-header"><div><p>{{ mode === "create" ? "Nuevo registro" : "Editar registro" }}</p><h3>{{ mode === "create" ? "Crear examen" : "Editar examen" }}</h3></div><BioNexusDialogCloseButton @click="close" /></header><section class="dialog-body exam-body"><div class="exam-main-grid"><BioNexusFormField label="Descripcion" field-id="exam-description" :error="descriptionError" required><input id="exam-description" ref="firstInput" v-model="draft.description" class="bio-nexus-field" maxlength="60" /></BioNexusFormField><BioNexusFormField label="Abreviatura" field-id="exam-abbreviation" :error="abbreviationError" required><input id="exam-abbreviation" v-model="draft.abbreviation" class="bio-nexus-field" maxlength="10" /></BioNexusFormField><BioNexusFormField label="Impuesto" field-id="exam-tax"><select id="exam-tax" v-model.number="draft.tax_id" class="bio-nexus-field"><option v-for="tax in taxes" :key="tax.id" :value="tax.id">{{ tax.description }} ({{ tax.value.toFixed(2) }}%)</option></select></BioNexusFormField><label class="exam-check"><input v-model="draft.special_test" type="checkbox" /><span>Prueba especial</span></label></div><section class="exam-price-panel"><h4>Tarifas</h4><div class="exam-price-grid"><BioNexusFormField v-for="number in 6" :key="number" :label="'Precio ' + number" :field-id="'exam-cost-' + number"><input :id="'exam-cost-' + number" v-model.number="draft['cost' + number]" class="bio-nexus-field" type="number" min="0" step="0.01" /></BioNexusFormField></div></section><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error" role="alert">{{ errorMessage }}</div></section><footer class="dialog-footer"><button type="button" class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close"><BioNexusActionIcon action="cancel" />Cancelar</button><button type="submit" class="bio-nexus-action bio-nexus-action-primary" :disabled="submitDisabled"><BioNexusActionIcon action="save" />{{ saving ? "Guardando..." : mode === "create" ? "Crear" : "Guardar" }}</button></footer></form></dialog></template>
<script setup>
import { computed,nextTick,reactive,ref } from "vue";import BioNexusActionIcon from "@/components/ui/BioNexusActionIcon.vue";import BioNexusDialogCloseButton from "@/components/ui/BioNexusDialogCloseButton.vue";import BioNexusFormField from "@/components/ui/BioNexusFormField.vue";
const props=defineProps({saving:{type:Boolean,default:false},canCreate:{type:Boolean,default:false},canUpdate:{type:Boolean,default:false},taxes:{type:Array,default:()=>[]},group:{type:Object,default:null}});const emit=defineEmits(["submit"]);const dialog=ref(null),firstInput=ref(null),mode=ref("create"),current=ref(null),errorMessage=ref(""),attempted=ref(false),original=ref("");const draft=reactive({description:"",abbreviation:"",tax_id:1,special_test:false,cost1:0,cost2:0,cost3:0,cost4:0,cost5:0,cost6:0});const values=computed(()=>({group_id:props.group?.id||0,description:draft.description.trim().toUpperCase(),abbreviation:draft.abbreviation.trim().toUpperCase(),tax_id:Number(draft.tax_id)||0,special_test:Boolean(draft.special_test),cost1:Number(draft.cost1)||0,cost2:Number(draft.cost2)||0,cost3:Number(draft.cost3)||0,cost4:Number(draft.cost4)||0,cost5:Number(draft.cost5)||0,cost6:Number(draft.cost6)||0}));const signature=computed(()=>JSON.stringify(values.value));const descriptionError=computed(()=>attempted.value&&!values.value.description?"La descripcion es obligatoria.":"");const abbreviationError=computed(()=>attempted.value&&!values.value.abbreviation?"La abreviatura es obligatoria.":"");const invalidPrice=computed(()=>[1,2,3,4,5,6].some(n=>!Number.isFinite(Number(draft['cost'+n]))||Number(draft['cost'+n])<0));const submitDisabled=computed(()=>props.saving||invalidPrice.value||signature.value===original.value||(mode.value==="create"?!props.canCreate:!props.canUpdate));function show(){dialog.value?.showModal();nextTick(()=>firstInput.value?.focus())}function assign(row){draft.description=row?.description||"";draft.abbreviation=row?.abbreviation||"";draft.tax_id=row?.tax_id||props.taxes[0]?.id||1;draft.special_test=Boolean(row?.special_test);for(let n=1;n<=6;n++)draft['cost'+n]=Number(row?.['cost'+n])||0;original.value=JSON.stringify(values.value)}function openCreate(){mode.value="create";current.value=null;assign(null);original.value="";attempted.value=false;errorMessage.value="";show()}function openEdit(row){mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";show()}function close(){if(dialog.value?.open)dialog.value.close()}function clearError(){errorMessage.value=""}function setError(message){errorMessage.value=String(message||"")}function submit(){attempted.value=true;if(descriptionError.value||abbreviationError.value||submitDisabled.value)return;emit("submit",{mode:mode.value,record:current.value,values:values.value})}defineExpose({openCreate,openEdit,close,clearError,setError});
</script><style scoped>.exam-dialog{width:min(860px,calc(100vw - 32px));padding:0;border:1px solid var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md)}.exam-body{display:grid;gap:var(--bio-nexus-space-4);max-height:70vh;overflow:auto}.exam-main-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:var(--bio-nexus-space-3);align-items:center}.exam-price-panel{padding:var(--bio-nexus-space-3);border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md)}.exam-price-panel h4{margin:0 0 var(--bio-nexus-space-3);color:var(--bio-nexus-color-primary-strong)}.exam-price-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--bio-nexus-space-3)}.exam-check{display:flex;align-items:center;gap:var(--bio-nexus-space-2)}@media(max-width:720px){.exam-main-grid,.exam-price-grid{grid-template-columns:1fr}}</style>
